index db28111..0e52a49 100644
--- a/src/notes.ts
+++ b/src/notes.ts
@@ -1,3 +1,11 @@
+import { parseTags } from "./tags.js";
+
 export function splitNotes(text: string): string[] {
   return text.split("\n");
 }
+
+/** The note lines that carry `tag`, matched without case and with or without the #. */
+export function notesWithTag(text: string, tag: string): string[] {
+  const wanted = tag.replace(/^#/, "").toLowerCase();
+  return splitNotes(text).filter((line) => parseTags(line).includes(wanted));
+}
diff --git a/src/tags.ts b/src/tags.ts
new file mode 100644
index 0000000..9d43162
--- /dev/null
+++ b/src/tags.ts
@@ -0,0 +1,6 @@
+const TAG = /(?:^|\s)#([a-z0-9-]+)/gi;
+
+/** The tags in one line, lowercased and without the #, in the order they appear. */
+export function parseTags(line: string): string[] {
+  return [...line.matchAll(TAG)].map((match) => (match[1] ?? "").toLowerCase());
+}
