+++ b/test/tags.test.ts
@@ -0,0 +1,7 @@
+import { expect, it } from "vitest";
+import { parseTags } from "../src/tags.js";
+
+it("reads the tags in a line, lowercased and without the #", () => {
+  expect(parseTags("buy milk #Home #errands")).toEqual(["home", "errands"]);
+  expect(parseTags("see issue#4 at a@b.com")).toEqual([]);
+});
